:root {
  --bg-1: #050b1a;
  --bg-2: #0d1730;
  --hud: rgba(10, 16, 30, 0.7);
  --panel: rgba(9, 20, 39, 0.88);
  --panel-border: rgba(152, 235, 255, 0.5);
  --text: #eefbff;
  --muted: #9ec5dd;
  --cyan: #6be8ff;
  --blue: #7e9bff;
  --purple: #b794ff;
  --red: #ff5d7d;
  --gold: #ffd56a;
  --green: #78ffc1;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  min-height: 100%;
  height: 100%;
  font-family: Inter, "Segoe UI", sans-serif;
  background: radial-gradient(circle at top, #111f40 0%, var(--bg-2) 25%, var(--bg-1) 80%);
  color: var(--text);
}

body {
  display: grid;
  place-items: center;
  overflow: hidden;
  user-select: none;
}

.app-shell {
  width: min(96vw, 1100px);
  height: min(96vh, 760px);
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 12px;
  padding: 12px;
  border-radius: 22px;
  background: rgba(6, 13, 25, 0.62);
  border: 1px solid rgba(146, 206, 255, 0.24);
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.45);
}

.hud {
  display: grid;
  grid-template-columns: repeat(4, minmax(90px, 1fr));
  gap: 10px;
  padding: 10px 12px;
  background: var(--hud);
  border: 1px solid rgba(114, 151, 255, 0.4);
  border-radius: 16px;
  backdrop-filter: blur(6px);
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 54px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(173, 219, 255, 0.2);
}

.label {
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

.stat span:last-child {
  font-size: clamp(1.1rem, 2vw, 1.8rem);
  font-weight: 800;
}

.game-wrap {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(28, 40, 70, 0.88), rgba(6, 13, 25, 0.9));
  border: 1px solid rgba(130, 194, 255, 0.35);
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  background: radial-gradient(circle at 50% 20%, rgba(111, 149, 255, 0.18), rgba(4, 9, 20, 0.9) 48%, rgba(0, 0, 0, 0.95));
  touch-action: none;
}

.overlay {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(2, 6, 15, 0.56);
  backdrop-filter: blur(2px);
}

.overlay.visible {
  display: flex;
}

.panel {
  width: min(90%, 440px);
  text-align: center;
  padding: 28px 22px 20px;
  border-radius: 20px;
  background: var(--panel);
  border: 1px solid var(--panel-border);
  box-shadow: 0 20px 44px rgba(0, 0, 0, 0.32);
}

.eyebrow {
  margin: 0 0 8px;
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--cyan);
}

h1 {
  margin: 0 0 12px;
  font-size: clamp(2rem, 3vw, 3rem);
}

#message {
  margin: 0 0 18px;
  line-height: 1.6;
  color: var(--muted);
}

button {
  font: inherit;
}

#startButton {
  appearance: none;
  border: 0;
  border-radius: 999px;
  padding: 0.9rem 1.4rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: linear-gradient(135deg, var(--cyan), var(--blue));
  color: #031520;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 12px 28px rgba(92, 142, 255, 0.35);
}

#startButton:active {
  transform: translateY(1px) scale(0.99);
}

.touch-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  padding-bottom: max(12px, env(safe-area-inset-bottom));
}

.control {
  flex: 1;
  max-width: 150px;
  min-height: 54px;
  border: 1px solid rgba(166, 217, 255, 0.45);
  border-radius: 14px;
  background: rgba(18, 31, 52, 0.82);
  color: var(--text);
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  touch-action: manipulation;
  cursor: pointer;
}

.control:active, .control.active {
  background: rgba(110, 184, 255, 0.18);
}

@media (max-width: 640px) {
  .app-shell {
    width: 100vw;
    height: 100vh;
    border-radius: 0;
    padding: 10px;
  }

  .hud {
    grid-template-columns: repeat(2, minmax(80px, 1fr));
  }

  .touch-controls {
    gap: 8px;
  }
}

