.panel { width: min(92%, 460px); padding: 26px 26px 22px; text-align: center; border: 2px solid rgba(255, 229, 151, .8); border-radius: 22px; background: linear-gradient(160deg, rgba(28, 49, 77, .97), rgba(13, 27, 49, .97)); box-shadow: 0 22px 60px rgba(7, 18, 38, .4); }
.eyebrow { margin: 0 0 7px; color: #ffe17c; text-transform: uppercase; letter-spacing: .17em; font-weight: 800; font-size: .72rem; }
