button { font: inherit; }
#startButton { border: 0; border-radius: 999px; padding: .9rem 1.5rem; background: linear-gradient(#ffe37c, #ffae42); color: #422817; font-weight: 1000; letter-spacing: .06em; text-transform: uppercase; cursor: pointer; box-shadow: 0 5px 0 #a85a32, 0 12px 25px rgba(0,0,0,.25); }
#startButton:active { transform: translateY(3px); box-shadow: 0 2px 0 #a85a32; }
