const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const overlay = document.getElementById('overlay');
const titleText = document.getElementById('title');
const messageText = document.getElementById('message');
const startButton = document.getElementById('startButton');
const scoreEl = document.getElementById('score');
const coinsEl = document.getElementById('coins');
const livesEl = document.getElementById('lives');
const bestEl = document.getElementById('best');

const W = canvas.width;
const H = canvas.height;
const WORLD_WIDTH = 4300;
const FLOOR_Y = 510;
const input = { left: false, right: false, jump: false };
const bestKey = 'sunny-side-best';

const platforms = [
  { x: 0, y: FLOOR_Y, w: 1080, h: 90 },
  { x: 1220, y: FLOOR_Y, w: 800, h: 90 },
  { x: 2150, y: FLOOR_Y, w: 830, h: 90 },
  { x: 3100, y: FLOOR_Y, w: 1200, h: 90 },
  { x: 300, y: 405, w: 150, h: 24 },
  { x: 555, y: 330, w: 145, h: 24 },
  { x: 815, y: 405, w: 155, h: 24 },
  { x: 1280, y: 400, w: 160, h: 24 },
  { x: 1535, y: 325, w: 150, h: 24 },
  { x: 1790, y: 405, w: 145, h: 24 },
  { x: 2260, y: 390, w: 170, h: 24 },
  { x: 2515, y: 315, w: 160, h: 24 },
  { x: 2780, y: 395, w: 150, h: 24 },
  { x: 3220, y: 410, w: 160, h: 24 },
  { x: 3480, y: 335, w: 160, h: 24 },
  { x: 3750, y: 410, w: 160, h: 24 }
];

const coinSpots = [
  [225, 455], [350, 360], [430, 455], [600, 285], [675, 455], [850, 360], [1010, 455],
  [1135, 420], [1295, 350], [1380, 455], [1580, 280], [1700, 455], [1840, 355], [1975, 455],
  [2085, 430], [2290, 340], [2375, 455], [2560, 270], [2700, 455], [2820, 345], [2945, 455],
  [3030, 420], [3260, 360], [3380, 455], [3525, 290], [3650, 455], [3795, 360], [3940, 455], [4110, 455]
];
const enemySeeds = [
  { x: 470, min: 455, max: 740 }, { x: 940, min: 860, max: 1030 },
  { x: 1430, min: 1370, max: 1950 }, { x: 2320, min: 2220, max: 2460 },
  { x: 2860, min: 2780, max: 2940 }, { x: 3330, min: 3180, max: 3430 },
  { x: 3870, min: 3790, max: 4070 }
];

const state = {
  running: false,
  score: 0,
  coins: 0,
  lives: 3,
  best: Number(localStorage.getItem(bestKey) || 0),
  camera: 0,
  time: 0,
  particles: [],
  hero: { x: 72, y: FLOOR_Y - 44, w: 30, h: 42, vx: 0, vy: 0, facing: 1, grounded: false, invuln: 0, checkpoint: 72 },
  coinsOnMap: [],
  enemies: []
};

function resetLevel() {
  state.hero = { x: 72, y: FLOOR_Y - 44, w: 30, h: 42, vx: 0, vy: 0, facing: 1, grounded: false, invuln: 0, checkpoint: 72 };
  state.coinsOnMap = coinSpots.map(([x, y]) => ({ x, y, taken: false, bob: Math.random() * Math.PI * 2 }));
  state.enemies = enemySeeds.map((e, i) => ({ ...e, y: FLOOR_Y - 29, w: 34, h: 29, dir: i % 2 ? -1 : 1, alive: true, phase: Math.random() * 3 }));
  state.particles = [];
  state.camera = 0;
  state.time = 0;
}

function updateHud() {
  scoreEl.textContent = String(state.score);
  coinsEl.textContent = String(state.coins);
  livesEl.textContent = String(state.lives);
  bestEl.textContent = String(state.best);
}

function overlayShow(title, message, button) {
  titleText.textContent = title;
  messageText.textContent = message;
  startButton.textContent = button;
  overlay.classList.add('visible');
}
function startGame() {
  state.score = 0;
  state.coins = 0;
  state.lives = 3;
  resetLevel();
  state.running = true;
  overlay.classList.remove('visible');
  updateHud();
}
function endGame(won) {
  state.running = false;
  if (state.score > state.best) {
    state.best = state.score;
    localStorage.setItem(bestKey, String(state.best));
  }
  updateHud();
  if (won) overlayShow('You made it!', `The whole valley is cheering! You collected ${state.coins} coins and scored ${state.score}.`, 'Play Again');
  else overlayShow('Adventure Over', `You scored ${state.score}. Take a breath, then give the valley another try!`, 'Try Again');
}

function burst(x, y, color, count = 10) {
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = 45 + Math.random() * 150;
    state.particles.push({ x, y, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed, life: .45 + Math.random() * .45, color, size: 3 + Math.random() * 4 });
  }
}

function overlaps(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

function hurt() {
  const h = state.hero;
  if (h.invuln > 0) return;
  state.lives -= 1;
  burst(h.x + h.w / 2, h.y + h.h / 2, '#fff0bd', 18);
  if (state.lives <= 0) {
    state.lives = 0;
    updateHud();
    endGame(false);
    return;
  }
  h.x = h.checkpoint;
  h.y = FLOOR_Y - h.h - 2;
  h.vx = 0;
  h.vy = 0;
  h.invuln = 1.7;
  state.camera = Math.max(0, h.x - 280);
}

function update(dt) {
  if (!state.running) return;
  state.time += dt;
  const h = state.hero;
  const previousBottom = h.y + h.h;
  const previousTop = h.y;

  const direction = (input.right ? 1 : 0) - (input.left ? 1 : 0);
  if (direction) {
    h.vx = direction * 270;
    h.facing = direction;
  } else {
    h.vx *= Math.pow(.001, dt);
  }
  if (input.jump && h.grounded) {
    h.vy = -610;
    h.grounded = false;
  }
  if (!input.jump && h.vy < -185) h.vy = -185;

  h.x += h.vx * dt;
  for (const p of platforms) {
    if (!overlaps(h, p)) continue;
    if (h.vx > 0) h.x = p.x - h.w;
    else if (h.vx < 0) h.x = p.x + p.w;
    h.vx = 0;
  }
  h.x = Math.max(0, Math.min(WORLD_WIDTH - h.w, h.x));

  h.vy += 1550 * dt;
  h.y += h.vy * dt;
  h.grounded = false;
  for (const p of platforms) {
    if (h.x + h.w <= p.x || h.x >= p.x + p.w) continue;
    if (h.vy >= 0 && previousBottom <= p.y + 4 && h.y + h.h >= p.y) {
      h.y = p.y - h.h;
      h.vy = 0;
      h.grounded = true;
    } else if (h.vy < 0 && previousTop >= p.y + p.h && h.y <= p.y + p.h) {
      h.y = p.y + p.h;
      h.vy = 20;
    }
  }

  if (h.x > 1190 && h.checkpoint < 1220) h.checkpoint = 1240;
  if (h.x > 3030 && h.checkpoint < 3100) h.checkpoint = 3120;
  if (h.y > H + 100) hurt();
  h.invuln = Math.max(0, h.invuln - dt);

  for (const coin of state.coinsOnMap) {
    if (coin.taken) continue;
    const cy = coin.y + Math.sin(state.time * 4 + coin.bob) * 4;
    if (h.x + h.w > coin.x - 12 && h.x < coin.x + 12 && h.y + h.h > cy - 14 && h.y < cy + 14) {
      coin.taken = true;
      state.coins += 1;
      state.score += 100;
      burst(coin.x, cy, '#ffe36b', 8);
    }
  }

  for (const e of state.enemies) {
    if (!e.alive) continue;
    e.x += e.dir * 62 * dt;
    if (e.x < e.min || e.x + e.w > e.max) e.dir *= -1;
    e.y = FLOOR_Y - e.h + Math.sin(state.time * 5 + e.phase) * 2;
    if (overlaps(h, e)) {
      if (h.vy > 80 && previousBottom <= e.y + 13) {
        e.alive = false;
        h.vy = -360;
        state.score += 200;
        burst(e.x + e.w / 2, e.y + e.h / 2, '#ffb17a', 14);
      } else {
        hurt();
      }
    }
  }

  for (const p of state.particles) {
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.vy += 300 * dt;
    p.life -= dt;
  }
  state.particles = state.particles.filter(p => p.life > 0);
  state.camera += (Math.max(0, Math.min(WORLD_WIDTH - W, h.x - W * .35)) - state.camera) * Math.min(1, dt * 5);
  if (h.x > 4130) endGame(true);
  updateHud();
}

function drawSky() {
  const gradient = ctx.createLinearGradient(0, 0, 0, H);
  gradient.addColorStop(0, '#72d5f7');
  gradient.addColorStop(.72, '#c2f0ff');
  gradient.addColorStop(1, '#e6f8d7');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = 'rgba(255,244,173,.95)';
  ctx.beginPath(); ctx.arc(790, 105, 45, 0, Math.PI * 2); ctx.fill();

  for (let i = 0; i < 7; i++) {
    const x = ((i * 223 - state.camera * .22) % (W + 240) + W + 240) % (W + 240) - 100;
    const y = 85 + (i % 3) * 61;
    ctx.fillStyle = 'rgba(255,255,255,.77)';
    ctx.beginPath(); ctx.ellipse(x, y, 35, 13, 0, 0, Math.PI * 2); ctx.ellipse(x + 24, y - 8, 24, 18, 0, 0, Math.PI * 2); ctx.ellipse(x + 47, y, 31, 12, 0, 0, Math.PI * 2); ctx.fill();
  }
  for (let i = 0; i < 9; i++) {
    const x = i * 190 - (state.camera * .38 % 190) - 30;
    const y = 400 + (i % 3) * 23;
    ctx.fillStyle = i % 2 ? '#7ec99b' : '#8bd5a5';
    ctx.beginPath(); ctx.ellipse(x, y, 140, 70, 0, Math.PI, Math.PI * 2); ctx.fill();
  }
}

function drawPlatforms() {
  for (const p of platforms) {
    const sx = p.x - state.camera;
    if (sx + p.w < -20 || sx > W + 20) continue;
    ctx.fillStyle = p.y === FLOOR_Y ? '#ad6942' : '#a66a43';
    ctx.fillRect(sx, p.y, p.w, p.h);
    ctx.fillStyle = '#55b84f';
    ctx.fillRect(sx, p.y, p.w, p.y === FLOOR_Y ? 13 : 8);
    ctx.fillStyle = 'rgba(255,224,153,.3)';
    for (let bx = sx + 10; bx < sx + p.w - 8; bx += 42) {
      ctx.fillRect(bx, p.y + 26, 22, 3);
      if (p.y !== FLOOR_Y) ctx.fillRect(bx + 8, p.y + 12, 3, 5);
    }
  }
}

function drawCoin(coin) {
  const x = coin.x - state.camera;
  if (x < -30 || x > W + 30 || coin.taken) return;
  const y = coin.y + Math.sin(state.time * 4 + coin.bob) * 4;
  ctx.fillStyle = '#f59e37'; ctx.beginPath(); ctx.ellipse(x, y, 10, 14, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#ffe77b'; ctx.beginPath(); ctx.ellipse(x - 2, y - 2, 6, 10, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#e69d28'; ctx.fillRect(x - 1, y - 5, 2, 10);
}

function drawEnemy(e) {
  if (!e.alive) return;
  const x = e.x - state.camera;
  if (x < -50 || x > W + 50) return;
  const bob = Math.sin(state.time * 8 + e.phase) * 2;
  ctx.fillStyle = '#a64c38'; ctx.beginPath(); ctx.ellipse(x + 17, e.y + 17 + bob, 17, 13, 0, Math.PI, 0); ctx.fill();
  ctx.fillStyle = '#f3b77f'; ctx.fillRect(x + 5, e.y + 19 + bob, 24, 7);
  ctx.fillStyle = '#fff'; ctx.fillRect(x + 8, e.y + 8 + bob, 7, 9); ctx.fillRect(x + 20, e.y + 8 + bob, 7, 9);
  ctx.fillStyle = '#25233a'; ctx.fillRect(x + 12, e.y + 12 + bob, 3, 4); ctx.fillRect(x + 23, e.y + 12 + bob, 3, 4);
  ctx.fillStyle = '#67382f'; ctx.fillRect(x + 3, e.y + 26 + bob, 10, 4); ctx.fillRect(x + 22, e.y + 26 + bob, 10, 4);
}

function drawHero() {
  const h = state.hero;
  if (h.invuln > 0 && Math.floor(state.time * 14) % 2 === 0) return;
  const x = h.x - state.camera;
  const running = Math.abs(h.vx) > 20 && h.grounded;
  const leg = running ? Math.sin(state.time * 18) * 4 : 0;
