  ctx.translate(x + h.w / 2, h.y);
  if (h.facing < 0) ctx.scale(-1, 1);
  // Original little adventurer: cap, scarf, tunic, boots.
  ctx.fillStyle = '#523b65'; ctx.fillRect(-13, 34 + leg, 11, 8); ctx.fillRect(3, 34 - leg, 11, 8);
  ctx.fillStyle = '#f2a45e'; ctx.fillRect(-11, 10, 22, 23);
  ctx.fillStyle = '#e95855'; ctx.fillRect(-14, 7, 28, 8); ctx.fillRect(-9, 0, 20, 9); ctx.fillRect(8, 4, 10, 5);
  ctx.fillStyle = '#ffe4ad'; ctx.fillRect(1, 15, 8, 7);
  ctx.fillStyle = '#283250'; ctx.fillRect(6, 17, 3, 3);
  ctx.fillStyle = '#4f9b72'; ctx.fillRect(-13, 28, 26, 8);
  ctx.fillStyle = '#f4cc67'; ctx.fillRect(-2, 29, 5, 5);
  ctx.fillStyle = '#f3a761'; ctx.fillRect(-14, 18, 5, 12); ctx.fillRect(9, 18, 5, 12);
