}

function drawGoal() {
  const x = 4180 - state.camera;
  ctx.fillStyle = '#f5f0d7'; ctx.fillRect(x, 265, 8, FLOOR_Y - 265);
  ctx.fillStyle = '#f45a67'; ctx.beginPath(); ctx.moveTo(x + 8, 270); ctx.lineTo(x + 70, 290); ctx.lineTo(x + 8, 312); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(x + 4, 260, 8, 0, Math.PI * 2); ctx.fill();
}

function render() {
  drawSky();
  drawPlatforms();
  for (const coin of state.coinsOnMap) drawCoin(coin);
  drawGoal();
  for (const enemy of state.enemies) drawEnemy(enemy);
  for (const p of state.particles) {
    ctx.globalAlpha = Math.min(1, p.life * 2);
    ctx.fillStyle = p.color; ctx.fillRect(p.x - state.camera, p.y, p.size, p.size);
  }
  ctx.globalAlpha = 1;
  drawHero();
  // Progress ribbon makes the destination easy to spot.
  ctx.fillStyle = 'rgba(19,46,66,.35)'; ctx.fillRect(20, 18, 180, 8);
  ctx.fillStyle = '#ffe178'; ctx.fillRect(20, 18, 180 * Math.min(1, state.hero.x / 4180), 8);
}

let lastFrame = 0;
function frame(now) {
  const dt = Math.min(.033, (now - (lastFrame || now)) / 1000 || .016);
