function setInput(code, pressed) {
  if (['ArrowLeft', 'KeyA'].includes(code)) input.left = pressed;
  if (['ArrowRight', 'KeyD'].includes(code)) input.right = pressed;
  if (['Space', 'ArrowUp', 'KeyW'].includes(code)) input.jump = pressed;
}

document.addEventListener('keydown', (event) => {
  if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'Space'].includes(event.code)) event.preventDefault();
  setInput(event.code, true);
});
document.addEventListener('keyup', (event) => setInput(event.code, false));
window.addEventListener('blur', () => { input.left = input.right = input.jump = false; });

for (const button of document.querySelectorAll('[data-control]')) {
  const control = button.dataset.control;
  const press = (event) => {
    event.preventDefault();
    button.classList.add('active');
    input[control] = true;
    if (button.setPointerCapture && event.pointerId !== undefined) button.setPointerCapture(event.pointerId);
  };
  const release = () => { button.classList.remove('active'); input[control] = false; };
  button.addEventListener('pointerdown', press);
  button.addEventListener('pointerup', release);
  button.addEventListener('pointercancel', release);
  button.addEventListener('lostpointercapture', release);
}
startButton.addEventListener('click', startGame);
resetLevel();
updateHud();
overlayShow('Sunny Side Quest', 'Run, jump, collect coins, and make it to the flag! Watch out for the grumpy critters.', 'Start Adventure');
render();
requestAnimationFrame(frame);

